mapper.select:
with insite_work_order as ( select 'Insite'::text as issue_type,
from v2_work_order w INNER JOIN asset_info a ON w.asset_id = a.id LEFT JOIN v2_service_request r ON w.sr_id = r.id where a.is_valid AND NOT a.is_deleted
AND EXISTS ( SELECT 1 FROM user_org uo WHERE uo.user_uid = #{userUid} AND uo.org_uid IN (a.tenant_uid, a.institution_uid, a.hospital_uid, a.site_uid, a.clinical_dept_uid, r.from_dept_uid) )
), mvs_work_order_mvs as ( select 'MVS'::text as issue_type,
from v2_work_order w INNER JOIN v2_service_request r ON w.sr_id = r.id INNER JOIN mvs_ib_mapping m1 ON w.asset_uid = m1.mvs_ib_uid INNER JOIN asset_info a ON m1.ib_uid = a.uid where a.is_valid AND NOT a.is_deleted
AND EXISTS ( SELECT 1 FROM user_org uo WHERE uo.user_uid = #{userUid} AND uo.org_uid IN (a.tenant_uid, a.institution_uid, a.hospital_uid, a.site_uid, a.clinical_dept_uid, r.from_dept_uid) )
), mvs_work_order_ehome as ( select 'MVS'::text as issue_type,
from v2_work_order w INNER JOIN v2_service_request r ON w.sr_id = r.id INNER JOIN mvs_ib_mapping m1 ON w.asset_uid = m1.e_home_ib_uid INNER JOIN asset_info a ON m1.ib_uid = a.uid where a.is_valid AND NOT a.is_deleted AND (m1.mvs_ib_uid IS NULL OR m1.mvs_ib_uid != m1.e_home_ib_uid)
AND EXISTS ( SELECT 1 FROM user_org uo WHERE uo.user_uid = #{userUid} AND uo.org_uid IN (a.tenant_uid, a.institution_uid, a.hospital_uid, a.site_uid, a.clinical_dept_uid, r.from_dept_uid) )
) select * from insite_work_order UNION ALL select * from mvs_work_order_mvs UNION ALL select * from mvs_work_order_ehome ORDER BY sr_request_time DESC
LIMIT #{pageSize} OFFSET #{offset}

with insite_work_order as ( select w.id from v2_work_order w INNER JOIN asset_info a ON w.asset_id = a.id LEFT JOIN v2_service_request r ON w.sr_id = r.id where a.is_valid AND NOT a.is_deleted
AND EXISTS ( SELECT 1 FROM user_org uo WHERE uo.user_uid = #{userUid} AND uo.org_uid IN (a.tenant_uid, a.institution_uid, a.hospital_uid, a.site_uid, a.clinical_dept_uid, r.from_dept_uid) )
), mvs_work_order_mvs as ( select w.id FROM v2_work_order w INNER JOIN v2_service_request r ON w.sr_id = r.id INNER JOIN mvs_ib_mapping m1 ON w.asset_uid = m1.mvs_ib_uid INNER JOIN asset_info a ON m1.ib_uid = a.uid where a.is_valid AND NOT a.is_deleted
AND EXISTS ( SELECT 1 FROM user_org uo WHERE uo.user_uid = #{userUid} AND uo.org_uid IN (a.tenant_uid, a.institution_uid, a.hospital_uid, a.site_uid, a.clinical_dept_uid, r.from_dept_uid) )
), mvs_work_order_ehome as ( select w.id FROM v2_work_order w INNER JOIN v2_service_request r ON w.sr_id = r.id INNER JOIN mvs_ib_mapping m1 ON w.asset_uid = m1.e_home_ib_uid INNER JOIN asset_info a ON m1.ib_uid = a.uid where a.is_valid AND NOT a.is_deleted AND (m1.mvs_ib_uid IS NULL OR m1.mvs_ib_uid != m1.e_home_ib_uid)
AND EXISTS ( SELECT 1 FROM user_org uo WHERE uo.user_uid = #{userUid} AND uo.org_uid IN (a.tenant_uid, a.institution_uid, a.hospital_uid, a.site_uid, a.clinical_dept_uid, r.from_dept_uid) )
) select count(*) from ( select id from insite_work_order UNION ALL select id from mvs_work_order_mvs UNION ALL select id from mvs_work_order_ehome ) t
